import random
import math

def pso(funcion_objetivo, dimensiones, n_particulas=30, iteraciones=100):
    # Inicializar partículas
    enjambre = []
    for _ in range(n_particulas):
        pos = [random.uniform(-10, 10) for _ in range(dimensiones)]
        vel = [random.uniform(-1, 1) for _ in range(dimensiones)]
        enjambre.append({"pos": pos, "vel": vel, "pbest": pos[:]})

    gbest = min(enjambre, key=lambda p: funcion_objetivo(p["pos"]))["pos"][:]
    w, c1, c2 = 0.7, 1.5, 1.5

    for _ in range(iteraciones):
        for particula in enjambre:
            for i in range(dimensiones):
                r1, r2 = random.random(), random.random()
                particula["vel"][i] = w*particula["vel"][i] + c1*r1*(particula["pbest"][i]-particula["pos"][i]) + c2*r2*(gbest[i]-particula["pos"][i])
                particula["pos"][i] += particula["vel"][i]
            if funcion_objetivo(particula["pos"]) < funcion_objetivo(particula["pbest"]):
                particula["pbest"] = particula["pos"][:]
            if funcion_objetivo(particula["pos"]) < funcion_objetivo(gbest):
                gbest = particula["pos"][:]
    return gbest, funcion_objetivo(gbest)

# Ejemplo: minimizar f(x,y) = x² + y²
def esfera(pos):
    return sum(p**2 for p in pos)

mejor, valor = pso(esfera, 2)
print(f"Mejor posición: {mejor}")
print(f"Valor mínimo: {valor}")
