# Sistema Experto simple para diagnóstico de problemas de PC

base_conocimiento = {
    "no_enciende": {
        "pregunta": "¿El computador no enciende en absoluto?",
        "condiciones": {"sin_luz": "si", "sin_sonido": "si"},
        "diagnostico": "Posible falla en la fuente de poder o placa madre"
    },
    "pantalla_azul": {
        "pregunta": "¿Ves una pantalla azul con texto?",
        "condiciones": {"sistema_operativo": "windows", "despues_de_actualizar": "si"},
        "diagnostico": "Conflicto de drivers después de actualización"
    },
    "lento": {
        "pregunta": "¿El computador funciona lentamente?",
        "condiciones": {"muchos_programas": "si", "disco_lleno": "si"},
        "diagnostico": "Fragmentación de disco y exceso de programas en inicio"
    },
}

def diagnosticar(sintomas):
    for problema, info in base_conocimiento.items():
        cumple = True
        for cond, valor in info["condiciones"].items():
            if sintomas.get(cond) != valor:
                cumple = False
                break
        if cumple:
            return info["diagnostico"]
    return "No se pudo determinar el problema"

# Ejemplo
sintomas = {"sin_luz": "si", "sin_sonido": "si"}
print(diagnosticar(sintomas))
