import numpy as np

class Perceptron:
    def __init__(self, n_entradas, tasa_aprendizaje=0.1):
        self.w = np.random.randn(n_entradas) * 0.01
        self.b = 0
        self.lr = tasa_aprendizaje

    def activacion(self, x):
        return 1 if x >= 0 else 0

    def predecir(self, X):
        return self.activacion(np.dot(self.w, X) + self.b)

    def entrenar(self, X, y, epocas=100):
        for epoca in range(epocas):
            errores = 0
            for xi, objetivo in zip(X, y):
                prediccion = self.predecir(xi)
                error = objetivo - prediccion
                self.w += self.lr * error * xi
                self.b += self.lr * error
                errores += abs(error)
            if errores == 0:
                break
        return epoca

# Compuerta AND
X = np.array([[0,0], [0,1], [1,0], [1,1]])
y = np.array([0, 0, 0, 1])

p = Perceptron(2)
p.entrenar(X, y)

for xi in X:
    print(f"{xi} -> {p.predecir(xi)}")
